import{_ as p,c as e,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"解","description":"高岛易断 - 解","frontmatter":{"title":"解","description":"高岛易断 - 解"},"headers":[],"relativePath":"zh/classics/takashima/040.md","filePath":"zh/classics/takashima/040.md"}'),i={name:"zh/classics/takashima/040.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="解" tabindex="-1">解 <a class="header-anchor" href="#解" aria-label="Permalink to “解”">​</a></h1><h2 id="解-1" tabindex="-1">解 <a class="header-anchor" href="#解-1" aria-label="Permalink to “解”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>解：利西南。无攸往，其来复吉。有攸往，夙吉。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>“解，缓也。”《坎》位北，《震》位东，自北转东，而南，而西，是行也，故曰“利西南”。《解》即所以解蹇，反东北而东南，倒《震》《坎》。《解》之西南，即《蹇》之西南也，故其利同。“无攸往”者，谓蹇解而难已平，无难则无所往，缓以养之，以俟来复，是以“来复吉”也。“有攸往”者，谓蹇解而难犹在，有难则必有往，急，不懈夙兴，是以“夙吉”也。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>雷雨作，解，君子以赦过宥罪。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>按：十二消息考，《坎》为十二月至正月之卦，《坎》五六两爻，值雨水惊蛰；《震》为二月至四月之卦，《震》初爻，值雷乃发声，三爻值谷雨。《解》为二月公卦，《象》曰“雷雨作”，盖因其时而取象焉。《坎》为罪，为灾，故有过有罪；《震》为缓，为生，故用“赦”用“宥”。君子法之，号令如雷之《震》，天下无不耸动，恩泽如雨之降，天下无不喜悦。夫使幽闭久系之人，一旦得“赦过宥罪”，弛其禁锢，脱其桎枯，如出陷阱而复见天日，则其忧闷郁结之气，无不解散。是君子与民更新，以之解万民之难也。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：灾难解脱，大有奋发振作之象。</p><p>○　问战征：威武一振，有大寇翦灭，小寇服从之象。</p><p>○　问功名：有声震百里，泽被群生之兆。</p><p>○　问营商：得时得令，“雷雨之动满盈”，大利。</p><p>○　问婚姻：《震》雷《坎》雨，阴阳交济，生育畅茂，吉。</p><p>○　问家宅：天盘有动，地盘有难，宜祈祷解免</p><p>○　问行人：一时可归，防小有灾难，无咎。</p><p>○　问讼事：幸得宽宥无罪。</p><p>○　问六甲：生男。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>初居《解》之始，大难初平，不求有功，只求无咎。初与四应，赖应之力，得解其险，故曰“无咎”。《象传》所谓“刚”者，指四，“柔”者指初，“际”者，谓初与四相应，阴阳相交，其义自可无咎也。</p><h2 id="初六占" tabindex="-1">初六占 <a class="header-anchor" href="#初六占" aria-label="Permalink to “初六占”">​</a></h2><p>○　问时运：困难初解，安时守分，自得无咎。</p><p>○　问战征：乍脱重围，宜自蓄锐养精，不可妄动，得保无咎</p><p>○　问营商：不致耗失，亦为幸矣。</p><p>○　问功名：目下只可守旧而已。</p><p>○　问家宅：平安无害。</p><p>○　问讼事：宜和。</p><p>○　问婚姻：平平。</p><p>○　问六甲：生男。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>明治二十四年三月，为郑永宁与清国公使馆内通书函，一时议论纷起，真伪莫辨，制纸分社长阳其二氏来书，请占一卦，以判虚实。筮得《解》之《归妹》。</p><p>断曰：《解》者，释也，坚冰得暖而解散之象也。初爻曰“无咎”，《易》之爻辞，单言“无咎”者，惟此一爻，是天张其口，以证郑氏之无罪也。且《解》者，谓解脱罪过，初爻之阴属郑氏，四爻之阳属清国公使，阴阳相应，知情分颇厚，然于国家大义，一无关害。《象传》曰“君子赦过宥罪”，料日后审官，亦必原情赦宥，断不以无稽文字，为之追究也。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>“田”者，猎也。上互《坎》，《坎》为狐，下互《离》，《离》为黄矢。狐阴兽，善惑人，故譬言妄邪小人，蛊惑君聪。“三”者，言数之多也。“黄”者，正色；“矢”者，直也。二爻以阳居阴，刚柔得中，上与六五，阴阳相应，为能辅佐大君，进贤黜邪，用以匡济时艰者也。盖欲解难，当先驱狐，故取《离》之矢，就《坤》之田，获《坎》之群狐而尽歼之，斯内治肃靖，于以济险出危，纳一世于中道，其在此矣，是以九二“贞吉”也。</p><h2 id="九二占" tabindex="-1">九二占 <a class="header-anchor" href="#九二占" aria-label="Permalink to “九二占”">​</a></h2><p>○　问时运：去邪归正，自得安吉。</p><p>○　问战征：“田”者猎兽，犹战之猎敌也。获狐者，犹获敌之渠魁也。得矢者，犹得敌之兵器也。故“贞吉”。</p><p>○　问营商：“田”者在猎兽，商者在猎利，“三”者多数，“黄”者黄金。必获厚利，吉。</p><p>○　问功名：曰“获”，曰“得”，功名可望，吉。</p><p>○　问家宅：此宅防有狐祟，须猎获之，乃吉。</p><p>○　问婚姻：此必先有小妾，而后纳正室也。黄者正色，为正配，吉。</p><p>○　问疾病：防是狐媚邪病，宜张弧矢以驱之，吉。</p><p>○　问六甲：生男。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>某商人占气运，筮得《解》之《豫》。</p><p>断曰：获狐得矢，知猎财猎名，无往不利。足下灾难既解，所求必得，正是好运发动，有雷雨得时之象。“黄”为正色，“矢”为直，又知足下品行正直，不惑于狐媚，是能以正治邪，故“贞吉”。</p><p>明治二十五年，余患鼻痔，呼吸不通，谈话亦困，颇觉苦之。闻金杉某，留学独逸，专修鼻科，归朝设院受诊，余欲求治，筮得《解》之《豫》。</p><p>断曰：内卦水险，外卦雷动，动而免险之象，故不宜坐视，宜速治疗，解去疾病之难也。占得第二爻，为《坎》之主，动而变《豫》，有预治之象。“田”为狩猎，“狐”为怪物，“黄矢”者，射其怪物之矢。今鼻中之疣，身之怪物也，“三”者，为数之多；“黄矢”者；想为医治之器也，爻可备观，其象则吉。余于是向金杉氏乞治，金杉氏一诊，许为易治，先用麻药，通电气于铜线，系挂于疣上，遂得截断其疣。疣数不一，悉皆截去，病苦顿解。医术之妙，实可惊喜，而《易》机之先示，悉合其状，更可惊叹。鸣呼！《易》者以森罗万象之事物，照彻于三百八十四爻之中，一一发露其灵机，以垂教于天下后世，圣人之所以为圣人也！</p><p>相州横须贺建筑炮台，又有造船大工场，年年埋筑海面，因采土炭岩石，向归大仓久米马担保，其岩石用船运至海岸筑处，并用小轮船为引，以取快疾。大仓组遂自造运船；免受雇船勒索等弊，指挥得当，独占利益。在官寮察知一人专担，难免弊窦，欲命高岛嘉兵卫分承其役，于是大仓组忌之，隐使船夫等百般妨碍，且故意宽支赁金，每日所损，不下七八百元，两家俱受其困。余乃请占一卦，筮得《解》之《豫》。</p><p>断曰：《彖传》谓“解，险以动，动而免乎险”，明言一动乃可出险。就占所言，爻以二五为纷争之主，今得二爻，二在内卦，属高岛氏，五在外卦，属大仓氏，二之负担，为四所妨，遂致互生吱唔，互受亏折。爻辞曰“三狐”，谓彼有三人，狡猾妨事；“黄矢”，谓我有一人，正直当事。以矢射狐，而狐退矣。四爻曰“朋至斯孚”，“朋”者，谓居间而讲和之友，“孚者，谓二五两主，得以感孚而罢争也。五本君子，始为小人所狐惑，故曰“君子有解，小人退也”。乃依此占，使横山孙一郎传高岛氏之意于大仓氏，事遂平和。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>“负”者，窃负，“乘”者，乘肥，“负且乘”，是窃盗而公卿也，故“可丑”。“致寇至”者，《坎》为寇。六三处《坎》体，本寇也，寇以遭时窃位，得以策肥乘坚，为寇者见之，曰彼亦寇也，今居然“负且乘”矣，是可取而代之也。此谓以寇名寇。当此险难甫解，而使寇者滥居高位，岂非用人者之咎乎？故曰“自我致戎”，咎复何辞？“吝”，即丑也。</p><h2 id="六三占" tabindex="-1">六三占 <a class="header-anchor" href="#六三占" aria-label="Permalink to “六三占”">​</a></h2><p>○　问时运：运非不佳，但因素行不端，为人鄙笑。</p><p>○　问战征：战隙自我而开，以致群盗纷起，一时难平。</p><p>○　问营商：防有盗劫之患。</p><p>○　问功名：沐猴而冠，其能久乎？</p><p>○　问家宅：门户不自谨慎，或用人不当，致招窃盗。</p><p>○　问婚姻：两姓均非端正之家，是富而不仁者也，“可丑”</p><p>○　问讼事：两造理皆不直。</p><p>○　问行人：满载而归，但来路不正。</p><p>○　问失物：已被窃负盗去，不得。</p><p>○　问六甲：生男。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>某人来，请占某区长品行，筮得《解》之《恒》。</p><p>断曰：负为肩负，小人之役也，乘为乘车，君子之分也，“负且乘”，是以小人而窃居君子之分也。寇者见之曰：是亦寇也，彼以寇显，我岂独不可显乎？故曰以寇招寇，丑有由来也。观此爻辞，则知某氏得为区长，亦寇取而得之，必有寇伺其后者也，何能久居其任乎？未几果罢职。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>四居《震》之始，《震》为足，“拇”，足大指也。四为《解》之主，《解》即解其蹇也。蹇为足疾，疾在一拇，不足以为《蹇》，解在一拇，亦不成其为《解》。四不当位，故不能全解其蹇，第见“解尔拇”，“拇”，即指四而汝也，故曰“尔拇”。《解》之四，即从《蹇》五来，《蹇》五曰“朋来”，故《解》四曰“朋至”。四亦自知其不能解蹇，惟望“朋至”，得以相助为理。将由拇以及心，斯心心相感，而《蹇》得全《解》矣。《坎》为孚，故曰“孚”。</p><h2 id="九四占" tabindex="-1">九四占 <a class="header-anchor" href="#九四占" aria-label="Permalink to “九四占”">​</a></h2><p>○　问时运：行年已当强仕，但行运不当，全在因人成事</p><p>○　问战征：防炮弹伤足，幸救兵得力，可以解围。</p><p>○　问营商：所获甚微，惟众心交孚，一二年后，可望厚利。</p><p>○　问功名：拇为足指，卑下已极，至五爻日“君子维有解”必待下科，可望登榜。</p><p>○　问家宅：此宅地低下，不得其当，只可作行栈店屋。</p><p>○　问婚姻：得有力媒人说合，方可成事。</p><p>○　问讼事：有朋友出，交相解劝，得可息讼。</p><p>○　问六甲：生男。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>群马县高崎市某甲书来，曰仆近邻有乙某者，一子罹病危笃，祷于榛名神社，不日而愈，乙某深喜之，偕子谒谢神社。一日乙某以遗金尽付其子曰：余居处，恐遭杀害，突然而行，同子即出而追寻，不知去向，举家不堪悲叹。请劳一占，以卜吉凶。余时适罹疾，因使门弟筮之，得《解》之《师》。</p><p>余见此占，问门弟将何以断之？门弟答曰：乙某不入山，亦不投水，在东方朋友之家而已。《彖传》曰，“解，险以动，动而免乎险”，乙某自言，恐遭杀害而逃去，是因险而动也；既得逃避，是“动而免乎险”也。爻辞曰“解而拇，朋至斯孚”，“拇”为足大指，父子一体，子在下，是足指也。遗金而别，解拇者也；“朋至斯孚”，是明言在朋友之家也。“孚”者，得朋友一言而心感也。余喜判语适当，遂书其断语而函告之。后面会某甲，询及此占，曰乙某踪迹，适如贵占云云。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>此“君子”，即《大象》所云“赦过宥罪”之“君子”也。五居尊位，与二相应，二既能得其中道，以祛群邪，许其更新，五即因之，原情赦宥，不复穷究，是以不解为《解》者也，小人遂感而有孚，是以吉也。《象传》曰，“君子有解，小人退也”，谓君子不必力去小人，小人自心服君子，不敢与君子同居。自古奸邪害政，皆由君子不能感化小人，小人是以不信服君子，以致倾轧。覆辙相寻，皆未明六五“有解”之旨也。</p><h2 id="六五占" tabindex="-1">六五占 <a class="header-anchor" href="#六五占" aria-label="Permalink to “六五占”">​</a></h2><p>○　问时运：正运亨通，群邪悉退。</p><p>○　问战征：不戮一人，不加一矢，外夷来服。</p><p>○　问功名：利君子，不利小人。</p><p>○　问营商：不劳苦计营谋，自然获利。</p><p>○　问家宅：此宅福曜照临，邪魔远避。</p><p>○　问婚姻：吉。</p><p>○　问行人：即归。</p><p>○　问疾病：外邪解散，正气来复，吉。</p><p>○　问讼事：理直者胜，理曲者服，即可罢讼。</p><p>○　问六甲：生男。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>友人横山孙一郎氏来，曰：近见新闻纸所揭福地氏下狱，想此老衰之身，际此炎暑，其困难不言可知。推其所由，为得金草文，在草文得金，与受贿营私者，固有别焉。公冶缧绁，孔子特以非罪明之，予将为福地氏筹一解救之方，请烦一占。筮得《解》之《困》。</p><p>断曰：《解》者，解散也。占得第五爻，为《解》之主，爻辞曰“君子维有解”，且系以“吉”，称曰“君子”，知罪非其罪，不以罪而贱其人也。曰“维有解，”知不解而解，不待救而自然脱罪也。曰“有孚于小人”，在被起事之小人，亦知陷害君子，于心不忍，自愿认罪而退也。福地氏暂受其厄，自得安吉。余因面东京裁判检事，具语此易，不日而福地氏出狱。阅后有相知永井泰次郎氏，以讼事嫌疑，牵连被引，伊妻来请一占，又得此爻，遂即将此判词告之。永井氏亦果以无罪放免。其事同，其爻同，其应验亦果相同，故附记之。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>《震》为诸侯，故称“公”；《坎》为弧，为弓，故曰“射”。卦体上互《离》，《离》为飞鸟，故有隼象；四动而成《坤》，《坤》为城墉，象城墉之上。上爻居《解》之极，自初至五，凡用刚，用柔，用猛，用宽，所以解除内难，亦既备矣，至上犹有飞翔在外，如鸷鸟之强悍者，五乃命六曰：公其乘《坤》之墉，张《离》之弧，抽一矢而射之，获其魁首，无不利也，以解悖也。《坎》为悖，谓灭此悖逆之徒，斯内患外寇，悉皆扫平矣。前诸爻，即《彖》所云“其来复吉”；上爻乃《彖》云“有攸往，夙吉”是也。</p><h2 id="上六占" tabindex="-1">上六占 <a class="header-anchor" href="#上六占" aria-label="Permalink to “上六占”">​</a></h2><p>○　问时运：运途吉顺，出外或遇小寇，宜急防之。</p><p>○　问战征：防有敌兵劫掠城外，宜高阜伏矢以射之，必有获也。</p><p>○　问营商：运货出外，防有盗劫，宜严备御，非特无失，且可以获盗粮也，故曰“无不利”。</p><p>○　问功名：爻称公，必已贵显也，当立功于外。</p><p>○　问家宅：墉墙宜高，可备外窃。</p><p>○　问婚姻：《诗》云“弋凫与雁”，有射之象，吉。</p><p>○　问讼事：悖逆自解，利。</p><p>○　问六甲：生男。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>镰仓圆觉寺住僧今北洪川和尚，博晓释典，当今之高僧也。予一日游镰仓，欲访和尚，意予所谈在《易》理，和尚所说在禅味，不知禅之三昧，与易之六爻，其旨果相符合否耶？试为一占，筮得《解》之《未济》。</p><p>断曰，佛法以解脱为宗旨，取解脱烦恼之义也。今得《解》上爻，不言《解》而言射，是用佛法，摄伏外魔，内性既定，外魔自消，与《解》所云之“三狐”为内魔，上之“隼”为外魔，其旨相同。知今日和尚，对余所谈，大旨如斯，予乃就卦义，书道歌一首，怀之以访和尚。和尚延予入禅堂，茗谈移晷，佛法《易》理，各极其妙，遂出道歌示之，一笑而别。</p><p>一日横滨商人左右田金作氏来访，请占利根运河株式高低。筮得《解》之《未济》。</p><p>断曰：《解》者，动而免险之卦。方今卖却株式，得此难得之利益，以免后日之灾，故曰“无不利”。恰如见隼集于高墉之上，一矢射之，以去后患，若迁延过时，及至《损》卦，必有损而无利也。氏从此言，一次卖之，即得利益；后因获利，而复买之，致招损失云。</p><p>明治三十一年，占伊藤内阁气运，筮得《解》之《未济》。</p><p>断曰：爻辞曰“公”，适合内阁之称也；内阁居高位，故曰“高墉”。“隼”，指政党首领而言。政党首领，身处位外，飞扬跋扈，每与政府为难，如隼之悍鸷善掠，残害善类，六五之君，命公乘高，射而获之。不曰歼而曰获，以隼本有用之材，素有功劳，故期获而用之，以收其效，故曰“获之，无不利”也。《象传》曰“解悖”，是谓《解》去悖逆之心，以冀归顺也。内阁躬膺总理，既修文德，又具武功，靖内难，戢外侮，固公之所优为，《解》之上而难解，正公今之时也。然《解》难为解，解位亦为解，尤公所宜慎审。遂呈此占于内阁，后内阁推荐大隈板垣两伯，问余以占断当否？余曰：执一隼，又欲获一隼，但恐所执之隼，振羽欲翔，放手遂不得复执；两隼相轧，而不能相容。公乃遂辞内阁，亦合《解》卦之义也。</p>',116)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
